class CodeforcesC : Runnable {

    val ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null

    lateinit var in: BufferedReader
    lateinit var out: PrintWriter
    var tok = StringTokenizer("")

    @Throws(FileNotFoundException::class)
    fun init() {
        if (ONLINE_JUDGE) {
            in = BufferedReader(InputStreamReader(System.`in`))
            out = PrintWriter(System.out)
        } else {
            in = BufferedReader(FileReader("input.txt"))
            out = PrintWriter("output.txt")
        }
    }

    @Throws(IOException::class)
    fun readString(): String? {
        while (!tok.hasMoreTokens()) {
            try {
                tok = StringTokenizer(in.readLine())
            } catch (e: Exception) {
                return null
            }
        }
        return tok.nextToken()
    }

    @Throws(IOException::class)
    fun readInt(): Int {
        return readString()?.toInt() ?: 0
    }

    @Throws(IOException::class)
    fun readLong(): Long {
        return readString()?.toLong() ?: 0L
    }

    @Throws(IOException::class)
    fun readDouble(): Double {
        return readString()?.toDouble() ?: 0.0
    }

    var timeBegin: Long = 0
    var timeEnd: Long = 0

    fun time() {
        timeEnd = System.currentTimeMillis()
        System.err.println("Time = " + (timeEnd - timeBegin))
    }

    var memoryTotal: Long = 0
    var memoryFree: Long = 0

    fun memory() {
        memoryFree = Runtime.getRuntime().freeMemory().toLong()
        System.err.println("Memory = " + ((memoryTotal - memoryFree) shr 10) + " KB")
    }

    val DEBUG = false

    fun debug(vararg objects: Any?) {
        if (DEBUG) {
            for (o in objects) {
                System.err.println(o.toString())
            }
        }
    }

    @Throws(IOException::class)
    fun readIntArray(n: Int): IntArray {
        val array = IntArray(n)
        for (i in 0 until n) {
            array[i] = readInt()
        }
        return array
    }

    override fun run() {
        try {
            timeBegin = System.currentTimeMillis()
            memoryTotal = Runtime.getRuntime().freeMemory().toLong()
            init()
            solve()
            out.close()
            time()
            memory()
        } catch (e: Exception) {
            e.printStackTrace(System.err)
            System.exit(-1)
        }
    }

    @Throws(IOException::class)
    fun solve() {
        val l = readInt()
        val r = readInt()

        val n = 9
        val ten = IntArray(n + 1)

        ten[0] = 1

        for (i in 1..n) {
            ten[i] = 10 * ten[i - 1]
        }

        var answer = 0L

        val luckyNumbers = ArrayList<Long>()

        for (length in 1..n) {
            for (cur in 0 until (1 shl length)) {
                var value = 0
                for (j in 0 until length) {
                    if (((1 shl j) and cur) == (1 shl j)) {
                        value += ten[j] * 7
                    } else {
                        value += ten[j] * 4
                    }
                }
                luckyNumbers.add(value.toLong())
            }
        }

        luckyNumbers.add(4444444444L)

        var lastNumber = l.toLong()

        for (luckyNumber in luckyNumbers) {
            if (luckyNumber > r.toLong()) {
                answer += (r.toLong() - lastNumber + 1) * luckyNumber
                break
            }
            if (luckyNumber >= l.toLong()) {
                answer += (luckyNumber - lastNumber + 1) * luckyNumber
                lastNumber = luckyNumber + 1
            }
        }

        out.println(answer)
    }
}

